// Organ — multisampled instrument (zones.json + audio in this folder), played by host.multisample.
// Generated by server/make-sample-plugin.js
export default function plugin(host) {
  const ms = host.multisample('zones.json', { defaults: {"velocity":0.15,"stereo":0.1} })
  return {
    type: "organ", name: host.plugin.name, desc: host.plugin.desc, family: host.plugin.family, range: host.plugin.range, sampled: 'multi',
    params: ms.params, create: ms.create, preload: ms.preload,
  }
}
